 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The cleaner helps the girl with her cello.","The man with the briefcase looks back as he boards.","The pigeon is sitting on a girder in paragraph 2.","The old couple travel on the train."],a=["T","F","T","T"],g=TF),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happen in the text.",items=["The pigeon hops down to inspect the glove.","The cleaner helps the girl with her cello.","The departure board flickers.","The train slides into the station."],a=[4,3,1,2],g=Q2),
 dict(d="2g",k="short",m=1,q="The roof is compared to “the ribs of some enormous sleeping creature”. What effect does this create?",a="It makes the station seem huge, alive and calm/quiet, as if it is asleep.",g="Accept any answer about size, life, sleep or stillness."),
 dict(d="2g",k="short",m=1,q="The people arrive “like ink spreading in water”. What does this suggest about how they arrive?",a="Slowly, gradually and quietly, spreading out one by one.",g="Accept: slowly / gradually / steadily / quietly / a few at a time."),
 dict(d="2d",k="short",m=2,q="The man holds his briefcase “against his chest as if it were a shield”. What does this suggest about how he feels? Explain your answer.",a="He feels nervous or defensive (1) because a shield protects someone, so the briefcase is something he uses to protect himself from worry (1).",g="1 mark for a suitable feeling (worried, nervous, tense, guarded). 1 mark for explaining the link to a shield or protection. Max 2."),
